const update = $input.first().json;
const message = update.message;
const allowedChatId = 'REPLACE_WITH_ALLOWED_TELEGRAM_CHAT_ID';
const allowedUserId = 'REPLACE_WITH_ALLOWED_TELEGRAM_USER_ID';
if (!message || String(message.chat?.id) !== allowedChatId ||
    String(message.from?.id) !== allowedUserId) return [];
const text = String(message.text || '').trim();
const input = text.replace(/^\/publish(?:@[A-Za-z0-9_]+)?\s+/i, '').trim();
// Accept a single URL directly as well as the explicit /publish command.
if (/\s/.test(input)) return [];
const url = input.replace(/[,.!?]+$/, '');
if (!url || !/^https:\/\/(?:www\.|m\.|vm\.|vt\.)?tiktok\.com\//i.test(url)) return [];
// The /publish command is the authorized operator's declaration that they have
// the rights to download and republish this video. The Publisher also validates.
return [{
  json: {
    request_key: 'tg_' + String(message.chat.id).replace('-', 'n') +
                 '_' + String(message.message_id) + '_publisher_v1',
    telegram_chat_id: String(message.chat.id),
    source_url: url,
    title: '',
    description: '',
    made_for_kids: false,
    rights_confirmed: true
  }
}];
